changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'air-quality.norm.pm2.5', '15', 'NUMBER', 'PM2.5 norm, ug/m3 (default: WHO 2021 24-hour guideline). A reading above it is EXCEEDED.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'air-quality.norm.pm2.5');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'air-quality.norm.pm10', '45', 'NUMBER', 'PM10 norm, ug/m3 (default: WHO 2021 24-hour guideline).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'air-quality.norm.pm10');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'air-quality.norm.no2', '25', 'NUMBER', 'NO2 norm, ug/m3 (default: WHO 2021 24-hour guideline).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'air-quality.norm.no2');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'air-quality.norm.so2', '40', 'NUMBER', 'SO2 norm, ug/m3 (default: WHO 2021 24-hour guideline).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'air-quality.norm.so2');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'air-quality.norm.o3', '100', 'NUMBER', 'O3 norm, ug/m3 (default: WHO 2021 peak-season guideline).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'air-quality.norm.o3');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'air-quality.norm.co', '4000', 'NUMBER', 'CO norm, ug/m3 (4000 = 4 mg/m3; default: WHO 2021 24-hour guideline).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'air-quality.norm.co');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'air-quality.alert.enabled', 'true', 'BOOLEAN', 'Raise an event when a station reading crosses above its norm. false = no threshold events at all.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'air-quality.alert.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.air-quality-exceeded.enabled', 'true', 'BOOLEAN', 'Notify the sanitary-epidemiological service users of the station territory when a pollutant crosses above its norm.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.air-quality-exceeded.enabled');
